/** SC26_0025_Spend and Save - April Hero -- generated by the template lab from Figma node 538:40114
 *  (SC26_0025_Spend and Save - April Hero). Everything is drawn from the board itself
 *  (FigmaLayers); the slots below are what a designer edits, each in its
 *  board place and stacking order:
 *    copy tied to the brief -- amount, lead, cta, urgency;
 *    board copy, editable -- flash-sale, text, off;
 *    photos -- photo; brand slots -- none.
 *  Text contracts come from each board layer (boardFit). NUDGE (./nudges.ts)
 *  holds the fix loop's per-layer corrections to Figma's render. */
import type { SheetAsset } from '../../../../../sheet/types';
import { Ground } from '../../../../../edit/Editable';
import { Picture } from '../../../../../edit/Picture';
import { ZONE_LIST, photoFor } from '../../../../../model/compose';
import { FigmaLayers, FigmaText, FigmaMark, type Slot } from '../../../../../render/figma/FigmaLayers';
import { cropOf, type FigmaLayout } from '../../../../../render/figma/layout';
import board from './layout.json';
import { NUDGE } from './nudges';

/** Which board layer each editable layer is, by the part of its id after the asset's. */
export const SC26_0025_SPEND_AND_SAVE_APRIL_HERO_538_40114_FIGMA = {
  "flash-sale": "538:40119", // text: FLASH SALE
  "amount": "538:40131", // amount: 70
  "text": "538:40134", // text: %
  "off": "538:40135", // text: OFF
  "lead": "538:40137", // lead: UP TO
  "cta": "538:40140", // cta: Shop Now
  "urgency": "538:40141", // urgency: ENDS TODAY
  "frame-2203/frame-2203": "538:40139", // pill: Frame 2203
  "removed": "538:40138", // remove: SC26_0025_Spend and Save - April Hero
} as const;

export function Sc260025SpendAndSaveAprilHero_538_40114({ asset }: { asset: SheetAsset }) {
  const layout = board as unknown as FigmaLayout, id = asset.id;
  const zone = ZONE_LIST.find(z => z.id === asset.media.photo) ?? photoFor('hike', 0);
  const slots: Record<string, Slot> = {
    [SC26_0025_SPEND_AND_SAVE_APRIL_HERO_538_40114_FIGMA["flash-sale"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/flash-sale`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [SC26_0025_SPEND_AND_SAVE_APRIL_HERO_538_40114_FIGMA["amount"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/amount`} contract="lab.amount" layout={layout}
      text={l.text!.chars.replace(/\d+/, (asset.copy.offer ?? '').match(/(\d+)\s*%/)?.[1] ?? (asset.copy.offer ?? '').match(/\d+/)?.[0] ?? '$&')} />,
    [SC26_0025_SPEND_AND_SAVE_APRIL_HERO_538_40114_FIGMA["text"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/text`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [SC26_0025_SPEND_AND_SAVE_APRIL_HERO_538_40114_FIGMA["off"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/off`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [SC26_0025_SPEND_AND_SAVE_APRIL_HERO_538_40114_FIGMA["lead"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/lead`} contract="lab.lead" layout={layout}
      text={asset.copy.lead ? (l.text!.chars.includes('\u2028') ? asset.copy.lead.replace(/\s+/, '\n') : asset.copy.lead) : l.text!.chars} />,
    [SC26_0025_SPEND_AND_SAVE_APRIL_HERO_538_40114_FIGMA["cta"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/cta`} contract="lab.cta" layout={layout}
      text={asset.copy.cta || l.text!.chars} />,
    [SC26_0025_SPEND_AND_SAVE_APRIL_HERO_538_40114_FIGMA["urgency"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/urgency`} contract="lab.urgency" layout={layout}
      text={asset.copy.urgency || asset.copy.marquee || asset.copy.eyebrow || l.text!.chars} />,
    [SC26_0025_SPEND_AND_SAVE_APRIL_HERO_538_40114_FIGMA["frame-2203/frame-2203"]]: (l, box, _n, board) => <>
      <FigmaMark l={l} box={box} id={`${id}/frame-2203/frame-2203/mark`} src="/graphics/named-sale-pill-475-98x119-3-8kzgr2.svg" fill="#F14222" layout={layout} />
      {board({ bare: true })}
    </>,
    [SC26_0025_SPEND_AND_SAVE_APRIL_HERO_538_40114_FIGMA["removed"]]: () => null,
  };
  const [w, h] = layout.size;
  // The frame's own photo, swappable, under every layer (and not drawn again by FigmaLayers).
  const photo = layout.frame.images?.[0] && layout.assets?.[layout.frame.images[0].ref];
  const crop = photo && layout.frame.crop ? cropOf(layout.frame.crop, [w, h], [photo.w, photo.h]) : undefined;
  const drawn = { ...layout, frame: { ...layout.frame, paints: layout.frame.paints?.filter(p => p.type !== 'IMAGE') } };
  // data-figma-compiled: the studio's Figma export reads a compiled board's way (toLayers).
  return <Ground id={`${id}/fill`} className="sheet" data-figma-compiled="" style={{ width: w, height: h, position: 'relative', overflow: 'hidden', background: '#fff' }}>
    <Picture id={`${id}/photo`} zone={zone} initialSrc={photo?.src} slot focus={crop?.focus}
      initialScale={crop?.initialScale} initialRotate={crop?.rotate} initialCrop={layout.frame.crop}
      style={{ position: 'absolute', inset: 0 }} />
    <FigmaLayers layout={drawn} slots={slots} nudges={NUDGE} />
  </Ground>;
}
